/**
 * Regenerate src/lib/health/schema-contract.generated.ts from
 * prisma/schema.prisma. Run after every schema change:
 *   npm run schema:contract
 * The deploy-boot-contracts test fails while the generated file is stale.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { parseSchemaContract } from "./schema-contract-parse";

const root = join(__dirname, "..");
const objects = parseSchemaContract(readFileSync(join(root, "prisma", "schema.prisma"), "utf-8"));
const body = objects
  .map((o) => (o.column ? `  { label: "${o.label}", table: "${o.table}", column: "${o.column}" },` : `  { label: "${o.label}", table: "${o.table}" },`))
  .join("\n");

writeFileSync(
  join(root, "src", "lib", "health", "schema-contract.generated.ts"),
  `// GENERATED by scripts/generate-schema-contract.ts from prisma/schema.prisma.
// Do not edit by hand: run \`npm run schema:contract\` after a schema change.
import type { RequiredSchemaObject } from "./schema-contract";

export const GENERATED_SCHEMA_OBJECTS: readonly RequiredSchemaObject[] = [
${body}
];
`
);
console.log(`schema contract: ${objects.length} objects`);
